39: func NewProposalGetCmd(option common.Options) *cobra.Command {
40: 	defaultPrintFlag := get.NewGetPrintFlags()
41: 	cmd := &cobra.Command{
42: 		Use: "proposal [NAME]",
43: 		Run: func(cmd *cobra.Command, args []string) {
44: 			cfg, err := clientcmd.BuildConfigFromKubeconfigGetter("", common.InKubeGetter)
45: 			if err != nil {
46: 				fmt.Fprintln(option.ErrOut, err)
47: 				return
48: 			}
49: 			cli, err := dynamic.NewForConfig(cfg)
50: 			if err != nil {
51: 				fmt.Fprintln(option.ErrOut, err)
52: 				return
53: 			}
54: 
55: 			list := corev1.List{
56: 				TypeMeta: v1.TypeMeta{
57: 					Kind:       "List",
58: 					APIVersion: "v1",
59: 				},
60: 				ListMeta: v1.ListMeta{},
61: 			}
62: 			var obj runtime.Object
63: 			if len(args) == 0 {
64: 				username := viper.GetString("auth.username")
65: 				organizations, err := cli.Resource(schema.GroupVersionResource{Group: common.IBPGroup, Version: common.IBPVersion, Resource: common.OrganizationResource}).List(context.TODO(), v1.ListOptions{
66: 					LabelSelector: fmt.Sprintf("bestchains.organization.admin=%s", username),
67: 				})
68: 				if err != nil {
69: 					fmt.Fprintln(option.ErrOut, err)
70: 					return
71: 				}
72: 				var proposalNames []string
73: 				for _, org := range organizations.Items {
74: 					namespace := org.GetName()
75: 					votes, err := cli.Resource(schema.GroupVersionResource{Group: common.IBPGroup, Version: common.IBPVersion, Resource: common.Vote}).Namespace(namespace).List(context.TODO(), v1.ListOptions{})
76: 					if err != nil {
77: 						fmt.Fprintln(option.ErrOut, err)
78: 						continue
79: 					}
80: 					for _, vote := range votes.Items {
81: 						proposalName := utils.GetNestedString(vote.Object, "spec", "proposalName")
82: 						proposalNames = append(proposalNames, proposalName)
83: 					}
84: 				}
85: 				for _, proposalName := range utils.RemoveDuplicateForStringSlice(proposalNames) {
86: 					proposal, err := cli.Resource(schema.GroupVersionResource{Group: common.IBPGroup, Version: common.IBPVersion, Resource: common.Proposal}).Get(context.TODO(), proposalName, v1.GetOptions{})
87: 					if err != nil {
88: 						fmt.Fprintln(option.ErrOut, err)
89: 						continue
90: 					}
91: 					list.Items = append(list.Items, runtime.RawExtension{Object: proposal})
92: 				}
93: 			} else {
94: 				for _, arg := range args {
95: 					proposal, err := cli.Resource(schema.GroupVersionResource{Group: common.IBPGroup, Version: common.IBPVersion, Resource: common.Proposal}).Get(context.TODO(), arg, v1.GetOptions{})
96: 					if err != nil {
97: 						fmt.Fprintln(option.ErrOut, err)
98: 						continue
99: 					}
100: 					list.Items = append(list.Items, runtime.RawExtension{Object: proposal})
101: 				}
102: 			}
103: 
104: 			if len(list.Items) != 1 {
105: 				listData, err := json.Marshal(list)
106: 				if err != nil {
107: 					fmt.Fprintln(option.ErrOut, err)
108: 					return
109: 				}
110: 				converted, err := runtime.Decode(unstructured.UnstructuredJSONScheme, listData)
111: 				if err != nil {
112: 					fmt.Fprintln(option.ErrOut, err)
113: 					return
114: 				}
115: 				obj = converted
116: 			} else {
117: 				obj = list.Items[0].Object
118: 			}
119: 
120: 			p, err := defaultPrintFlag.ToPrinter()
121: 			if err != nil {
122: 				fmt.Fprintln(option.ErrOut, err)
123: 				return
124: 			}
125: 			_ = p.PrintObj(obj, option.Out)
126: 		},
127: 	}
128: 	defaultPrintFlag.AddFlags(cmd)
129: 
130: 	return cmd
131: }
